class Solution {
  public String countAndSay(int n) {
    String cur = "1";
    for (int k = 1; k < n; k++) {
      StringBuilder sb = new StringBuilder();
      for (int i = 0; i < cur.length();) {
        int j = i;
        while (j < cur.length() && cur.charAt(j) == cur.charAt(i)) {
          j++;
        }
        sb.append(j - i).append(cur.charAt(i));
        i = j;
      }
      cur = sb.toString();
    }
    return cur;
  }
}

class Solution:
    def countAndSay(self, n: int) -> str:
        cur = "1"
        for _ in range(1, n):
            nxt = []
            i = 0
            while i < len(cur):
                j = i
                while j < len(cur) and cur[j] == cur[i]:
                    j += 1
                nxt.append(str(j - i))
                nxt.append(cur[i])
                i = j
            cur = "".join(nxt)
        return cur

impl Solution {
  pub fn count_and_say(n: i32) -> String {
    let mut cur = String::from("1");
    for _ in 1..n {
      let bytes = cur.as_bytes();
      let mut next = String::new();
      let mut i = 0;
      while i < bytes.len() {
        let mut j = i;
        while j < bytes.len() && bytes[j] == bytes[i] {
          j += 1;
        }
        next.push_str(&(j - i).to_string());
        next.push(bytes[i] as char);
        i = j;
      }
      cur = next;
    }
    cur
  }
}

const countAndSay = (n: number): string => {
  let cur = '1';
  for (let k = 1; k < n; k++) {
    let next = '';
    let i = 0;
    while (i < cur.length) {
      let j = i;
      while (j < cur.length && cur[j] === cur[i]) j++;
      next += `${j - i}${cur[i]}`;
      i = j;
    }
    cur = next;
  }
  return cur;
};
